        if cs[i] < '0' || cs[i] > '9' {
            return false
        }
        i += 1
    }
    true
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split(" ") {
        if t == "" {
            continue
        }
        if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b = st.pop().unwrap_or(0)
            let a = st.pop().unwrap_or(0)
            if t == "+" {
                st.push(a + b)
            } else if t == "-" {
                st.push(a - b)
            } else if t == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else if is_int(t) {
            let v: int = t.parse::<int>().unwrap_or(0)
            st.push(v)
